from statistics import median as stats_median

class TestMedianFunction(unittest.TestCase):

    def test_list_with_even_number_of_elements(self):
        self.assertEqual(median([3, 1, 2]), (1 + 2) / 2)

    def test_list_with_odd_number_of_elements(self):
        self.assertEqual(median([3, 1, 2, 4]), 2.5)

    def test_empty_list_should_raise_error(self):
        with self.assertRaises(ValueError):
            median([])

    def test_median_returns_float_for_even_count_integers(self):
        l = [1, 2]
        expected_result = (1 + 2) / 2
        result = stats_median(l)
        self.assertEqual(result, expected_result)

    def test_median_returns_int_when_possible_and_list_has_odd_length(self):
        for i in range(5):
            l = [i] * 3
            with self.subTest(i=i): # to make the test independent and run them as a group.
                result = stats_median(l)
                expected_result = l[0]
                self.assertEqual(result, expected_result)

    def test_median_returns_float_for_even_count_floats(self):
        for i in range(5):
            l = [float(i)] * 4
            with self.subTest(i=i): # to make the test independent and run them as a group.
                result = stats_median(l)
                expected_result = (i + (i+1) / 2.0)
                if i % 2 == 0:
                    self.assertAlmostEqual(result, expected_result)
                else:
                    self.assertEqual(result, int(i))

    def test_list_with_all_same_elements(self):
        for l in ([3], [4]):
            with self.subTest(l=l): # to make the test independent and run them as a group.
                result = stats_median(l)
                expected_result = float(l[0])
                self.assertEqual(result, expected_result)

    def test_list_with_integers_and_floats(self):
        l = [1.5, 2, 3]
        with self.subTest():
            # Check if the function can handle mixed types.
            result = stats_median(l)
            expected_result = (l[0] + l[2]) / 2
            self.assertEqual(result, expected_result)

    def test_list_with_large_values(self):
        for i in range(1001): 
